// lib/osint/layers/eyes/index.ts
// ─────────────────────────────────────────────────────────────────────────────
// OSINT Layer Eyes: Public Webcams & Official Traffic Cameras
//
// ═════════════════════════════════════════════════════════════════════════════
// WINDY WEBCAMS API v3 — MANDATORY LICENSE COMPLIANCE (L1 – L9)
// ═════════════════════════════════════════════════════════════════════════════
//
// L1. TOKEN EXPIRATION (10-MINUTE HARD LIMIT):
//     Image URLs generated by the API are secured by access tokens that expire
//     after 10 minutes on the Free Tier (HTTP 401).
//     ENFORCEMENT: Metadata is cached for 6 hours, but image URLs are cached
//     for a maximum of 8 minutes (2-minute buffer). Image URLs must NEVER be
//     stored in persistent databases or long-term storage.
//
// L2. PROHIBITION OF CONTINUOUS SCANNING / AUTOMATED HARVESTING:
//     "Continuous scanning of a significant number of webcams" and "intensive usage
//     of any API endpoint by means of automated software" are strictly forbidden.
//     ENFORCEMENT: refreshMs is set to 0 (ZERO background polling). Fetches are
//     strictly user-initiated (viewport pan/zoom with 800ms debounce, or clicking
//     a specific webcam). No crawlers, no background refresh loops.
//
// L3. PROHIBITION OF REDISTRIBUTION & THIRD-PARTY SERVICE PROVISION:
//     Services may not be redistributed or exposed as a public API to third parties.
//     ENFORCEMENT: The /api/osint/eyes route checks Origin/Referer headers to serve
//     only our frontend and is not documented as an open API. Raw Windy responses
//     are normalized and never exposed as an unconstrained proxy.
//
// L4. PROHIBITION OF PUBLISHING GRAPHICS / COMPOSITING:
//     "Publishing graphics displaying the Webcam images" is forbidden.
//     ENFORCEMENT: No screenshot tools, image download buttons, collage generators,
//     or image export features exist in the UI. Images are view-only.
//
// L5. PROHIBITION OF IMAGE STRETCHING (ORIGINAL RESOLUTION CAP):
//     Webcam images must only be displayed at their original size or smaller.
//     ENFORCEMENT: The WebcamViewer uses CSS `object-fit: contain` and constrains
//     container styles to `maxWidth: imageWidth` and `maxHeight: imageHeight`.
//     Small images are never upscaled or stretched with unconstrained width: 100%.
//
// L6. PRESERVATION OF ADVERTISEMENTS:
//     Windy reserves the right to deliver ads on the Free Tier; blocking them
//     constitutes a material breach.
//     ENFORCEMENT: No DOM filtering or ad-blocking scripts are applied to Windy elements.
//
// L7. MANDATORY ATTRIBUTION WITH SPECIFIC LINKS:
//     Attribution must explicitly state:
//     "Webcams provided by windy.com - add new webcam"
//     with active links to https://www.windy.com/ and https://www.windy.com/webcams/add
//     ENFORCEMENT: The exact text and both active links appear prominently inside
//     the WebcamViewer modal and on the /osint/sumber attribution page.
//
// L8. NON-COMMERCIAL / UNMONETIZED COMPLIANCE:
//     The Free Tier must not be restricted to paid areas of an application.
//     ENFORCEMENT: Cakrapala is a 100% free, public, unmonetized open-source platform.
//
// L9. PROHIBITION OF INDIVIDUAL IDENTIFICATION / FACIAL RECOGNITION:
//     Attempting to identify individuals from webcam imagery is strictly forbidden.
//     ENFORCEMENT: No digital zoom enhancements, high-pass filtering, facial
//     recognition, or person-level bounding boxes are implemented.
// ═════════════════════════════════════════════════════════════════════════════

import type { BBox, LayerPayload, OsintEntity } from '@/lib/osint/types';
import type { FetchLayerParams, LayerFetcher } from '@/lib/osint/adapter';
import { wrapAdapter } from '@/lib/osint/adapter';
import { getOfficialWebcams } from './sources/official';
import {
  fetchWindyWebcams,
  getFreshWebcamImage,
  _resetWindyCacheForTesting,
} from './sources/windy';

export { getFreshWebcamImage, _resetWindyCacheForTesting };

export const MAX_EYES_CAP = 60;

export const rawFetchEyesLayer: LayerFetcher = async (
  params: FetchLayerParams,
): Promise<LayerPayload> => {
  const bbox = params.bbox;
  const fetchedAt = new Date().toISOString();

  // 1. Fetch official government cameras (always available, no API key needed)
  const officialEntities = getOfficialWebcams(bbox);

  // 2. Fetch Windy API v3 webcams
  const windyResult = await fetchWindyWebcams(bbox);
  const allEntities = [...officialEntities, ...windyResult.entities];

  // 3. Viewport proximity sorting and capping to 60 webcams (L2)
  let displayedEntities = allEntities;
  if (allEntities.length > MAX_EYES_CAP) {
    const centerLat = bbox ? (bbox[1] + bbox[3]) / 2 : -6.2;
    const centerLon = bbox ? (bbox[0] + bbox[2]) / 2 : 106.8;

    allEntities.sort((a, b) => {
      const distA = Math.hypot(a.position.lat - centerLat, a.position.lon - centerLon);
      const distB = Math.hypot(b.position.lat - centerLat, b.position.lon - centerLon);
      return distA - distB;
    });

    displayedEntities = allEntities.slice(0, MAX_EYES_CAP);
  }

  // 4. Handle missing API key notice
  let errorCode: string | null = null;
  if (windyResult.missingKey && officialEntities.length === 0) {
    errorCode = 'MISSING_KEY';
  } else if (windyResult.error === 'INVALID_API_KEY') {
    errorCode = 'INVALID_API_KEY';
  }

  return {
    layer: 'eyes',
    entities: displayedEntities,
    fetchedAt,
    upstreamAt: fetchedAt,
    stale: false,
    error: errorCode,
  };
};

export const fetchEyesLayer: LayerFetcher = wrapAdapter('eyes', rawFetchEyesLayer);
